function useHashRoute(){
  const initial=location.hash.slice(1)||'/operations/visits';
  const [route,setRouteState]=useState(initial);
  React.useEffect(()=>{ const fn=()=>setRouteState(location.hash.slice(1)||'/operations/visits'); addEventListener('hashchange',fn); return()=>removeEventListener('hashchange',fn)},[]);
  const go=(path)=>{ location.hash=path; setRouteState(path); window.scrollTo({top:0,behavior:'smooth'}); };
  return [route,go];
}

const cls=(...v)=>v.filter(Boolean).join(' ');
const Icon=({name})=><span className="icon" aria-hidden="true">{{calendar:'▣',user:'●',clock:'◷',alert:'!',safe:'◆',doc:'▤',check:'✓',spark:'✦',health:'✚',scale:'⚖\uFE0E',gift:'❖',refresh:'↻',star:'★',link:'⛓\uFE0E',case:'◎',edu:'✎',warn:'⚠\uFE0E',record:'▤',home:'⌂',search:'⌕',chev:'›',close:'×',plus:'＋',arrow:'→'}[name]||'•'}</span>;

function Badge({tone='neutral',icon,children}){ return <span className={`badge ${tone}`}>{icon?<Icon name={icon}/>:<span className="badge-dot"/>}{children}</span> }
function Button({children,tone='default',onClick,type='button'}){ return <button type={type} className={`button ${tone}`} onClick={onClick}>{children}</button> }
function LanguageSelector(){
  const {language,setLanguage,languages}=useI18n();
  const [open,setOpen]=useState(false);
  const pickerRef=React.useRef(null);
  const current=languages.find(option=>option.value===language)||languages[0];
  React.useEffect(()=>{
    if(!open)return undefined;
    const close=event=>{if(!pickerRef.current?.contains(event.target))setOpen(false)};
    const escape=event=>{if(event.key==='Escape')setOpen(false)};
    document.addEventListener('pointerdown',close);
    document.addEventListener('keydown',escape);
    return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',escape)};
  },[open]);
  return <div className="language-picker" ref={pickerRef} data-i18n-ignore>
    <button className="language-trigger" type="button" aria-label="Language" aria-haspopup="menu" aria-expanded={open} onClick={()=>setOpen(value=>!value)}><span>Language</span><b>{current.shortLabel}</b><span className="language-chevron" aria-hidden="true">⌄</span></button>
    {open&&<div className="language-menu" role="menu">{languages.map(option=><button type="button" role="menuitemradio" aria-checked={option.value===language} className={option.value===language?'active':''} key={option.value} onClick={()=>{setLanguage(option.value);setOpen(false)}}><span>{option.label}</span><small>{option.shortLabel}</small></button>)}</div>}
  </div>
}
function Card({children,className='',onClick}){ return <section className={cls('card',onClick&&'clickable',className)} onClick={onClick}>{children}</section> }
function SectionTitle({title,desc,action}){ return <div className="section-title"><div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{action&&<div className="section-actions">{action}</div>}</div> }
function Metric({label,value,desc,tone='teal',icon}){ return <div className="metric"><span className={`metric-icon ${tone}`}><Icon name={icon||'doc'}/></span><div><small>{label}</small><strong>{value}</strong><span>{desc}</span></div></div> }
function MetricStrip({items,className=''}){ return <Card className={cls('metric-strip',className)}>{items.map((x,i)=><Metric key={i}{...x}/>)}</Card> }
function Progress({value,tone='teal'}){ return <div className="progress"><span className={tone} style={{width:`${value}%`}}/></div> }
function Donut({value=67,label='오늘 방문',main='28/42'}){ const r=59.5,cx=71,cy=71,circ=2*Math.PI*r,dash=(value/100)*circ; return <div className="donut-stat"><strong className="donut-title">{label}</strong><div className="donut-wrap"><svg className="donut-svg" width="142" height="142" viewBox="0 0 142 142"><circle cx={cx} cy={cy} r={r} fill="none" stroke="#e9edef" strokeWidth="23"/><circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--teal)" strokeWidth="23" strokeDasharray={`${dash} ${circ-dash}`} strokeLinecap="round" transform={`rotate(-90 ${cx} ${cy})`}/></svg><div className="donut-inner"><strong>{main}</strong><span>{value}% 완료</span></div></div></div> }
function Search({value,onChange,placeholder='이름을 검색하세요'}){return <label className="search"><Icon name="search"/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>}
function Select({children,options=['확인 필요','진행 중','완료']}){ return <select defaultValue="all"><option value="all">{children}</option>{options.map(o=><option key={o}>{o}</option>)}</select> }
function DateFilter(){const date=useSelectedDate();return <label><span>기준일</span><input type="date" value={toISO(date)} onChange={e=>e.target.value&&setSelectedDate(e.target.value)}/></label>}
const defaultFilterFields=[{label:'전체 상태'},{label:'담당 직원'},{label:'제공 서비스'}];
function Filters({search,setSearch,extra=true,fields,date=true,onReset}){const list=fields||(extra?defaultFilterFields:[]);const reset=()=>{resetSelectedDate();onReset?.()};return <Card className="filters">{date&&<DateFilter/>}{list.map(f=>f.search?<label className="filter-search" key={f.label}><span>{f.label}</span><Search value={f.value} onChange={f.onChange} placeholder={f.placeholder}/></label>:<label key={f.label}><span>{f.label}</span>{f.render||<Select options={f.options}>{f.all||'전체'}</Select>}</label>)}{setSearch&&<label className="filter-search"><span>검색</span><Search value={search} onChange={setSearch}/></label>}<Button onClick={reset}>초기화</Button></Card> }

function ModalSection({title,children,className}){return <section className={cls('modal-section',className)}>{title&&<h3>{title}</h3>}{children}</section>}
function RecordBody({head,signal,notice,plan,planSummary,quote,transcript,summary,ai,groups,visits,conclusion,fields,message}){return <div className="record-body">{head&&<div className="record-head"><div><strong>{head.subject}</strong><span>{head.meta}</span></div>{head.status&&<Badge tone={head.status[1]}>{head.status[0]}</Badge>}</div>}{signal&&<div className="record-signal"><Icon name="alert"/><span>{signal}</span></div>}{notice&&<p className="record-notice">{notice}</p>}{message&&<p className="record-message">{message}</p>}{plan&&<ModalSection title={<>계획 대비 수행 <small data-i18n-ignore>{planSummary}</small></>}><div className="record-plan">{plan.map(p=><div key={p.cat}><Badge tone={p.tone}>{p.cat}</Badge><span className="record-plan-items">{p.done.join(' · ')}{p.missing?.map(m=><span className="record-missing" key={m.item}>{m.item} — {m.reason}</span>)}</span><b className={p.missing?.length?'partial':''} data-i18n-ignore>{`${p.done.length}/${p.done.length+(p.missing?.length||0)}`}</b></div>)}</div></ModalSection>}{transcript&&<ModalSection title="시간대별 원문"><ol className="record-transcript">{transcript.map(([t,text])=><li key={t}><time>{t}</time><blockquote>{text}</blockquote></li>)}</ol></ModalSection>}{quote&&<ModalSection title="요양보호사 원문"><blockquote className="record-quote">{quote}</blockquote></ModalSection>}{summary&&<ModalSection title="기록 정리"><div className="record-summary">{summary.map(([k,v])=><div key={k}><small>{k}</small><p>{v}</p></div>)}</div></ModalSection>}{groups&&groups.map(g=><ModalSection key={g.title} title={<>{g.title} <small data-i18n-ignore>{g.count}</small></>}><ul className="record-list">{g.rows.map(([d,a,t])=><li key={d+t}><time>{d}</time><span>{a}</span><p>{t}</p></li>)}</ul></ModalSection>)}{visits&&<ModalSection title="최근 4회 방문"><div className="record-visits"><div className="th"><span>날짜</span><span>거부 표현</span><span>직원 대응</span><span>설명·동의 확인</span></div>{visits.map(v=><div key={v[0]}><span>{v[0]}</span><span className={v[1]==='거부'?'refuse':''}>{v[1]}</span><span>{v[2]}</span><span className="ok">✓ {v[3]}</span></div>)}</div></ModalSection>}{fields&&<dl className="record-fields">{fields.map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>}{conclusion&&<ModalSection title="확인 결과 요약"><p className="record-conclusion">{conclusion}</p></ModalSection>}{ai&&<ModalSection className="record-ai" title={<><Badge tone="purple">AI 정리</Badge><span className="ai-state">{ai.state}</span></>}><p>{ai.text}</p></ModalSection>}</div>}
const countOf=(done,total,language)=>({ko:`${total}개 중 ${done}개 수행`,en:`${done} of ${total} done`,ja:`${total}項目中${done}項目実施`}[language]);
function VisitRecordBody({visit}){const language=useLanguage();const today=formatShortDate(getToday(),language);if(visit.recipient==='홍○○'){const plan=[{cat:'신체활동',tone:'teal',done:['세면','목욕','이동','옷 갈아입기']},{cat:'인지·정서',tone:'blue',done:['말벗','불안 완화']},{cat:'가사·일상',tone:'neutral',done:['세탁'],missing:[{item:'주변 정돈',reason:'시간 부족으로 다음 방문'}]}];return <RecordBody head={{subject:<>홍○○ 어르신 · <span data-i18n-ignore>{visit.time}</span></>,meta:<><time data-i18n-ignore>{today}</time> · 김○○ 요양보호사 · 음성 기록 10:58 작성</>,status:['관리자 확인 필요','warning']}} plan={plan} planSummary={countOf(7,8,language)} quote="“처음엔 목욕 안 한다고 하셨는데, 물 온도를 직접 손으로 확인하시게 하니까 괜찮다고 하시면서 하셨어요. 오늘은 머리 감을 때도 편안해 보이셨어요. 세탁은 했는데 방 정리는 시간이 모자라서 다음에 하기로 했어요.”" ai={{state:'직원 확인 완료',text:'목욕 시작 전 거부 의사 표현 → 물 온도 직접 확인 지원 후 참여. 최근 4회 중 3회 같은 반응이 기록되어 개선 활동 “목욕 시작 전 순서 설명”과 연결됩니다.'}}/>}const pending=visit.status==='예정'||visit.status.startsWith('지연');const progress=visit.status==='진행 중';const written=visit.record==='작성 완료';const status=pending?['작성 전','neutral']:progress?['작성 중','blue']:written?['직원 작성 완료','success']:['작성 전','neutral'];const message=pending?'방문 전이라 아직 기록이 없어요.':progress?'방문 중이에요. 방문이 끝나면 기록이 올라와요.':written?'기록이 작성됐어요. 시연용 원문은 홍○○ 어르신 기록에서 볼 수 있어요.':'기록이 아직 작성되지 않았어요. 담당 요양보호사에게 작성을 요청해 주세요.';return <RecordBody head={{subject:<>{visit.recipient} 어르신 · <span data-i18n-ignore>{visit.time}</span></>,meta:<><time data-i18n-ignore>{today}</time> · {visit.staff} 요양보호사</>,status}} message={message}/>}
function DailyRecordBody({d,full}){return <RecordBody head={{subject:<>홍○○ 어르신 · {d.steps[0][1]}</>,meta:full?'김○○ 요양보호사 · 음성 3분 12초':'김○○ 요양보호사 · 음성 기록',status:['직원 작성 완료','success']}} transcript={full?[['09:12','“목욕하자고 하니까 오늘은 안 한다고 하셨어요. 물이 뜨거울까 봐 걱정하시는 것 같았어요.”'],['09:18','“그래서 순서를 먼저 말씀드리고, 물 온도를 직접 손으로 확인해 보시라고 했어요.”'],['09:25','“확인하시더니 괜찮다고 하시면서 하셨어요. 상체는 직접 씻으셨어요.”'],['10:05','“예정보다 15분 정도 더 걸렸어요. 다음에도 물 온도 먼저 확인하시게 하면 좋을 것 같아요.”']]:undefined} quote={full?undefined:d.source} summary={d.steps.slice(2).map(([k,v])=>[k.replace(/^[③④⑤⑥] /,''),v])} ai={{state:d.aiState,text:d.aiText}}/>}
function MonthlyEvidenceBody(){const language=useLanguage();const n=c=>({ko:`${c}건`,en:`${c}`,ja:`${c}件`}[language]);const groups=monthlyEvidenceGroups.map(g=>({...g,count:n(g.rows.length)}));return <RecordBody head={{subject:'홍○○ 어르신',meta:<><span data-i18n-ignore>{formatMonth(getToday(),language)}</span> · AI 요약이 참고한 기록</>}} groups={groups}/>}
function RightsRecordBody(){return <RecordBody head={{subject:'홍○○ 어르신',meta:'최근 4회 방문 · 김○○ 요양보호사',status:['확인 필요','danger']}} signal="확인 필요 신호: 반복되는 강한 거부 · 개인별 계획 반영 전" notice="AI는 문제를 확정하지 않고 관련 기록을 묶어 담당자의 확인을 돕습니다." visits={[['09.08','거부','순서 설명 후 참여','동의 확인'],['09.11','거부','물 온도 확인 후 참여','동의 확인'],['09.15','없음','평소대로 진행','동의 확인'],['09.18','거부','목욕 대신 세면만 진행','수급자 의사 존중']]} conclusion="강요 없이 설명과 선택권을 제공한 기록입니다. 반복되는 불안을 개인별 계획에 반영할지 검토가 필요합니다."/>}
function ConsultRecordBody(){return <RecordBody head={{subject:'김○○ 어르신 상담',meta:'09.23 상담 · 이○○ 사회복지사',status:['개선 중','warning']}} fields={[['참석자','김○○ 어르신 · 김○○ 보호자(자녀) · 이○○ 사회복지사'],['주제','보호자 요청과 수급자의 외출 선호 차이'],['수급자 의견','“오후에 동네 공원에 잠깐이라도 나가고 싶어요.”'],['보호자 의견','“혼자 나가시다 넘어질까 걱정돼요. 누가 같이 있을 때만 나가셨으면 해요.”'],['합의 내용','방문 시간 중 요양보호사 동행 외출을 주 1회 시범 운영한다. 날씨와 컨디션을 먼저 확인한다.'],['다음 확인','10.07 · 동행 외출 2회 후 수급자 만족도와 안전 확인']]}/>}
function ModalFooter({close,nav,secondary,primary}){return <footer>{nav&&<div className="modal-nav-actions"><Button onClick={()=>{close();location.hash=nav.to}}>{nav.label} <Icon name="chev"/></Button></div>}<Button onClick={close}>닫기</Button>{secondary&&<Button onClick={()=>{secondary.onClick?.();close()}}>{secondary.label}</Button>}{primary&&<button type="button" className="button primary" disabled={primary.disabled} onClick={()=>{if(primary.to){close();location.hash=primary.to;return}primary.onClick?.();if(!primary.stay)close()}}>{primary.label}</button>}</footer>}
function ModalShell({close,children,...footer}){return <><div className="modal-body"><div className="record-body">{children}</div></div><ModalFooter close={close} {...footer}/></>}
function SummaryLine({items}){return <div className="summary-line">{items.map((x,i)=><span key={i}>{x}</span>)}</div>}
function InfoList({rows}){return <dl className="record-fields">{rows.map(([k,v])=><div key={typeof k==='string'?k:undefined}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>}
function ChoiceList({options,value,onChange}){return <div className="judgment-options" role="radiogroup">{options.map(o=><button type="button" key={o.label} role="radio" aria-checked={value===o.label} className={cls('judgment-option',value===o.label&&'selected')} onClick={()=>onChange(o.label)}><span className="radio-dot" aria-hidden="true"/><span><strong>{o.label}</strong>{o.desc&&<small>{o.desc}</small>}</span>{o.recommended&&<Badge tone="teal">추천</Badge>}</button>)}</div>}
function CheckList({items}){return <div className="modal-checks">{items.map(([label,checked])=><label key={label}><input type="checkbox" defaultChecked={checked}/><span>{label}</span></label>)}</div>}
const hasBatchim=w=>{const c=w.charCodeAt(w.length-1)-0xAC00;return c>=0&&c<=11171&&c%28!==0&&c%28!==8};
function registerLabel(label,language){if(language==='en')return `Register: ${translateText(label,'en')}`;if(language==='ja')return `「${translateText(label,'ja')}」で登録`;return `${label}${hasBatchim(label)?'으로':'로'} 등록`}
function IssueBody({close,summary,sections,todo,primary,secondary,nav}){return <ModalShell close={close} primary={primary} secondary={secondary} nav={nav}>{summary&&<SummaryLine items={summary}/>}{sections.map(([title,content])=><ModalSection key={title} title={title}>{typeof content==='string'?<p className="record-conclusion">{content}</p>:content}</ModalSection>)}{todo&&<ModalSection title="지금 할 일" className="record-todo"><ul>{todo.map(t=><li key={t}>{t}</li>)}</ul></ModalSection>}</ModalShell>}
function VisitRows({rows}){return <div className="record-visits impact-rows">{rows.map(r=><div key={r[0]}>{r.map((c,i)=>i===r.length-1?<span key={i}><Badge tone={c==='대체 필요'?'danger':'warning'}>{c}</Badge></span>:<span key={i}>{c}</span>)}</div>)}</div>}
function SupportActionBody({close,onConfirm}){const language=useLanguage();const[choice,setChoice]=useState(null);return <IssueBody close={close} summary={['박○○ 요양보호사',<><time data-i18n-ignore>{formatShortDate(addDays(getToday(),-1),language)}</time> 접수</>,'미확인']} sections={[['요청 내용','“근무 중 허리가 불편해서 오후 목욕 지원 일정을 조정하고 싶어요.”'],['영향 일정 2건','화 14:00 목욕 지원 · 목 14:00 목욕 지원'],['조치 선택지',<ChoiceList options={[{label:'오후 일정 다른 직원과 교대'},{label:'신체 부담 적은 서비스로 조정'},{label:'건강 상담 안내'}]} value={choice} onChange={setChoice}/>],['참고','최근 3개월 근무 194시간 · 연속 근무 최대 6일']]} primary={{label:'조치 방법 확정',disabled:!choice,onClick:onConfirm}}/>}
function WonAmount({n}){const language=useLanguage();const v=n.toLocaleString('en-US');return <span data-i18n-ignore>{language==='en'?`₩${v}`:language==='ja'?`${v}ウォン`:`${v}원`}</span>}
function AiBody({close,state='직원 확인 대기',children,primary,secondary}){return <ModalShell close={close} primary={primary} secondary={secondary}><div className="ai-head"><Badge tone="purple">AI 생성</Badge><Badge tone={state==='직원 확인 완료'?'success':state==='반려'?'neutral':'warning'}>{state}</Badge></div><p className="record-notice">기록과 계획을 바탕으로 한 제안입니다. 최종 결정은 관리자가 합니다.</p>{children}</ModalShell>}
