function AiEvidenceBody({close,focus}){const rows=[['원문 의견','홍○○ 어르신 · 09.22 10:10 · “오전보다 오후에 목욕하고 싶어요.”'],['보호자 요청','김○○ 보호자 · 09.21 16:20 · “가능하면 오전 중 목욕 완료 희망”'],['관련 돌봄 기록','최근 4회 중 3회 목욕 전 거부 표현(오전 방문)'],['개인별 계획','목욕 주 2회(화·목 오전) · 수행 방법 “순서 설명 → 물 온도 직접 확인”'],['추가 확인 정보','오후 목욕 가능 직원 2명 · 보호자 의견과 다를 때 수급자 의사 우선 확인(권리·인권 원칙)']];return <AiBody close={close}><dl className="record-fields">{rows.map(([k,v])=><div key={k} className={focus===k?'focused':''}><dt>{k}</dt><dd>{v}</dd></div>)}</dl></AiBody>}
function MonthlySummaryEditBody({close,text,onSave}){const language=useLanguage();const[value,setValue]=useState(()=>language==='ko'?text:translateText(text,language));return <ModalShell close={close} secondary={{label:'취소'}} primary={{label:'수정 저장',onClick:()=>onSave(value)}}><div className="ai-head"><Badge tone="purple">AI 월간 요약</Badge><Badge tone="warning">관리자 확인 필요</Badge></div><ModalSection title="요약 내용"><textarea className="modal-textarea" rows={7} value={value} onChange={e=>setValue(e.target.value)} data-i18n-ignore/><p className="record-notice">수정하면 작성 주체가 ‘AI 초안 · 사회복지사 수정’으로 바뀝니다.</p></ModalSection><ModalSection title="수정 이력"><p className="record-conclusion"><time data-i18n-ignore>{formatShortDate(getToday(),language)}</time> 10:35 AI 생성</p></ModalSection></ModalShell>}
function ChoiceDecisionBody({close,children,options,fixedLabel,onConfirm}){const language=useLanguage();const[choice,setChoice]=useState(null);return <ModalShell close={close} primary={{label:!choice?'판단을 선택하세요':fixedLabel||registerLabel(choice,language),disabled:!choice,onClick:()=>onConfirm?.(choice)}}>{children}<ModalSection title="선택지"><ChoiceList options={options} value={choice} onChange={setChoice}/></ModalSection></ModalShell>}
function RateCompare(){return <div className="compare modal-compare"><div><small>적용 전 거부율</small><strong>75%</strong><span>4회 중 3회</span></div><Icon name="arrow"/><div><small>적용 후 거부율</small><strong className="improved">33%</strong><span>3회 중 1회</span></div></div>}
function ApplyDots(){const language=useLanguage();return <div className="visit-dots"><div><small>적용 전</small><div>{applyVisits.before.map((r,i)=><VisitDot key={i} result={r} language={language}/>)}</div></div><div><small>적용 후</small><div>{applyVisits.after.map(([d,r])=><VisitDot key={d} result={r} date={d} language={language}/>)}{applyVisits.remaining.map(d=><VisitDot key={d} result="pending" date={d} language={language}/>)}</div></div></div>}
