function MessageDraftBody({close,onSend}){const language=useLanguage();const text='10월 첫 주부터 화·목 목욕 방문이 오후로 바뀝니다. 2주 동안 어르신 반응을 기록해 주세요.';const[value,setValue]=useState(()=>language==='ko'?text:translateText(text,language));return <ModalShell close={close} primary={{label:'전달하기',onClick:onSend}}><InfoList rows={[['받는 사람','김○○ 요양보호사(홍○○ 어르신 담당)'],['전달 방식','케어로그 앱 알림']]}/><ModalSection title="전달 내용 미리보기"><textarea className="modal-textarea" rows={4} value={value} onChange={e=>setValue(e.target.value)} data-i18n-ignore/></ModalSection></ModalShell>}
function WeeklyConfirmBody({close,onConfirm}){return <ModalShell close={close} primary={{label:'확인 완료',onClick:onConfirm}}><ModalSection title="이번 주 핵심 변화"><InfoList rows={[['목욕 전 불안','감소 · 서비스 순서 설명 후 참여한 기록이 3회 확인됨'],['식사량','관찰 · 평소의 약 70% 섭취가 2회 기록됨'],['수면','새 변화 · 밤중에 자주 깼다는 직접 의견 2회']]}/></ModalSection><ModalSection title="다음 주 확인사항"><CheckList items={[['목욕 전 순서 설명 유지',false],['물 온도 직접 확인하도록 지원',false],['식사량과 수분 섭취 관찰',false],['수면 변화 직접 의견 확인',false]]}/></ModalSection><ModalSection title="사회복지사 메모"><textarea className="modal-textarea" rows={3} placeholder="이번 주 확인 내용을 적어 주세요"/></ModalSection></ModalShell>}
function PeopleBody({close,target,children,next,primary}){return <ModalShell close={close} primary={primary}>{target&&<div className="record-head"><div><strong>{target}</strong></div></div>}{children}{next&&<ModalSection title="다음 할 일" className="record-todo"><ul><li>{next}</li></ul></ModalSection>}</ModalShell>}
