function Modal({modal,onClose}){ if(!modal)return null; return <div className="overlay" onMouseDown={onClose}><div className="modal" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><header><div><div className="modal-badges"><Badge tone={modal.tone||'teal'}>{modal.tag||'상세 정보'}</Badge>{modal.badge2&&<Badge tone={modal.badge2[1]}>{modal.badge2[0]}</Badge>}</div><h2>{modal.title}</h2></div><div className="modal-header-actions">{modal.headerAction&&<Button tone="primary" onClick={modal.onHeaderAction||onClose}>{modal.headerAction}</Button>}<button className="close" onClick={onClose}><Icon name="close"/></button></div></header>{modal.render?modal.render({close:onClose}):<><div className="modal-body">{modal.body||<><div className="detail-grid"><div><small>담당자</small><strong>이○○ 사회복지사</strong></div><div><small>처리 기한</small><strong>2026.09.25</strong></div><div><small>상태</small><strong>확인 필요</strong></div></div><Card className="soft"><h3>확인 내용</h3><p>관련 기록과 최근 변화가 함께 표시됩니다. 담당자가 원본 기록을 확인한 뒤 다음 행동을 결정할 수 있습니다.</p></Card></>}</div><footer>{modal.actions?.length>0&&<div className="modal-nav-actions">{modal.actions.map(a=><Button key={a.label} onClick={()=>{onClose();location.hash=a.to}}>{a.label} <Icon name="chev"/></Button>)}</div>}<Button onClick={onClose}>닫기</Button>{!modal.hideConfirm&&<Button tone="primary" onClick={onClose}>{modal.confirmLabel||'확인 완료'}</Button>}</footer></>}</div></div> }

