function Attendance({open}){
  const date=useSelectedDate();
  const[status,setStatus]=useState('all');
  const[staff,setStaff]=useState('all');
  const[service,setService]=useState('all');
  const filtered=attendanceRows.filter(row=>(status==='all'||row.status===status)&&(staff==='all'||row.staff===staff)&&(service==='all'||row.service===service));
  const reset=()=>{resetSelectedDate();setStatus('all');setStaff('all');setService('all')};
  return <Page><MetricStrip items={[{label:'근태 정상률',value:'96.2%',desc:'최근 3개월'},{label:'근태 이상',value:'3건',desc:'지각 2 · 누락 1',tone:'orange'},{label:'휴가 예정',value:'2명',desc:'이번 주',tone:'blue'},{label:'수정 요청',value:'1건',desc:'관리자 승인',tone:'red'}]}/><Card className="filters"><label><span>기준일</span><input type="date" value={toISO(date)} onChange={e=>e.target.value&&setSelectedDate(e.target.value)}/></label><label><span>전체 상태</span><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">전체</option><option value="정상">정상</option><option value="지각">지각</option><option value="출근 누락">출근 누락</option><option value="조퇴">조퇴</option></select></label><label><span>담당 직원</span><select value={staff} onChange={e=>setStaff(e.target.value)}><option value="all">전체</option>{attendanceRows.map(row=><option key={row.staff} value={row.staff}>{row.staff}</option>)}</select></label><label><span>제공 서비스</span><select value={service} onChange={e=>setService(e.target.value)}><option value="all">전체</option><option value="방문요양">방문요양</option><option value="행정지원">행정지원</option></select></label><Button onClick={reset}>초기화</Button></Card><Card><SectionTitle title="기간별 근태 기록" action={<strong className="teal-text">총 {filtered.length}건</strong>}/><div className="table"><div className="tr attendance-grid th"><span>직원</span><span>예정 출근</span><span>실제 출근</span><span>예정 퇴근</span><span>실제 퇴근</span><span>근무시간</span><span>상태</span><span/></div>{filtered.map(row=><button className="tr attendance-grid" key={row.staff} onClick={()=>open({title:`${row.staff} 근태 상세`,tag:row.status,tone:row.tone})}><span>{row.staff}</span><span>{row.scheduledIn}</span><span>{row.actualIn}</span><span>{row.scheduledOut}</span><span>{row.actualOut}</span><span>{row.hours}</span><Badge tone={row.tone}>{row.status}</Badge><Icon name="chev"/></button>)}{!filtered.length&&<p className="empty-filter-results">선택한 조건에 해당하는 근태 기록이 없습니다.</p>}</div></Card></Page>
}

const matchTargets=[{name:'정○○ 어르신',type:'신규 배정',tone:'danger',summary:'첫 방문 09.30 오전'},{name:'홍○○ 어르신',type:'담당 변경',tone:'warning',summary:'인수인계 4/5 완료'}];
