function Matching({open}){const language=useLanguage();const[target,setTarget]=useState(0);const[assigned,setAssigned]=useState(null);const[pick,setPick]=useState(0);const t=matchTargets[target];const c=pick===null?null:matchCandidates[pick];return <Page><MetricStrip items={[{label:'매칭 요청',value:'4건',desc:'신규 2 · 변경 2'},{label:'확인 필요',value:'2건',desc:'이번 주 시작',tone:'red'},{label:'인수인계 중',value:'1건',desc:'첫 방문 전',tone:'orange'},{label:'이번 달 완료',value:'7건',desc:'평균 2.3일',tone:'green'}]}/><div className="matching-layout"><Card className="match-list"><SectionTitle title="배정이 필요한 수급자"/>{matchTargets.map((x,i)=>{const done=i===0&&assigned;return <button className={cls('match-target',target===i&&'selected')} key={x.name} onClick={()=>setTarget(i)}><Badge tone={done?'success':x.tone}>{done?'배정 완료':x.type}</Badge><div><strong>{x.name}</strong><p>{done?`${assigned} 배정 · 첫 방문 09.30 오전`:x.summary}</p></div><Icon name="chev"/></button>})}</Card>{target===0?<Card className="match-detail"><SectionTitle title={`${t.name} · 신규 배정`} desc="추천 조건과 현재 업무량을 함께 확인한 뒤 담당자를 결정합니다." action={<Button onClick={()=>open({title:'정○○ 어르신 매칭 요청',tag:'신규 배정',tone:'danger',render:({close})=><PeopleBody close={close} target="정○○ 어르신"><InfoList rows={[['요청','09.27 · 이○○ 사회복지사'],['필요 조건','오전 방문 · 이동지원 경험 · 강서구'],['첫 방문 희망','09.30 오전']]}/><p className="record-notice">추천 직원은 화면 오른쪽에서 선택합니다.</p></PeopleBody>})}>요청 상세</Button>}/><div className="need-chips">{['오전 방문','이동지원','강서구'].map(x=><span key={x}>{x}</span>)}</div><h3>추천 직원</h3><div className="candidate-list">{matchCandidates.map((x,i)=><Candidate key={x.name} {...x} selected={pick===i} onSelect={()=>setPick(i)}/>)}</div>{c?<div className="match-review"><div><h3>일치 이유</h3><ul className="reason-list">{c.reasons.map((r,i)=><li key={r} className={c.checks[i]?'ok':'warn'}><span aria-hidden="true">{c.checks[i]?'✓':'⚠'}</span>{r}</li>)}</ul></div><div><h3>배정 후 업무량</h3><div className="load-rows">{c.load.map(([label,before,after])=><div key={label}><small>{label}</small><span>{before}</span><span aria-hidden="true">→</span><strong className={c.within?'':'over'}>{after}</strong></div>)}</div><Badge tone={c.within?'success':'warning'} icon={c.within?'check':'alert'}>{c.within?'기준 이내':'기준 초과'}</Badge></div></div>:<p className="match-hint">추천 직원을 선택하면 일치 이유와 배정 후 업무량을 보여줍니다.</p>}<div className="match-footer"><strong>첫 방문 9월 30일 오전</strong><div><Button onClick={()=>setPick(null)}>다른 직원 선택</Button>{c&&<Button tone="primary" onClick={()=>open({title:`${c.name} → 정○○ 어르신 배정`,tag:'직원 매칭',tone:'teal',render:({close})=><PeopleBody close={close} target={`${c.name} 요양보호사`} primary={{label:'배정 확정',onClick:()=>setAssigned(c.name)}}><InfoList rows={[['배정 내용',<>{c.score} · 첫 방문 09.30 오전</>],['배정 후 업무량',<>{c.load.map(([label,b,a])=><span className="load-inline" key={label}>{label} {b} → {a}</span>)}</>]]}/><ModalSection title="알림 보낼 대상"><CheckList items={[[`${c.name} 요양보호사`,true],['정○○ 어르신 보호자',true]]}/></ModalSection></PeopleBody>})}>{`${c.name} 배정`}</Button>}</div></div></Card>:<Card className="match-detail"><SectionTitle title="담당자 변경·인수인계" desc="돌봄 목표, 선호, 주의사항, 최근 개선 활동을 전달합니다." action={<><Badge tone="blue">진행 중</Badge><Button onClick={()=>open({title:'홍○○ 어르신 담당자 변경',tag:'담당 변경',tone:'warning',render:({close})=><PeopleBody close={close} target="홍○○ 어르신"><InfoList rows={[['변경',<>김○○ → 박○○ · 시작 <time data-i18n-ignore>{formatShortDate(addDays(getToday(),handoverStart),language)}</time></>],['사유','김○○ 요양보호사 담당 조정(업무량) · 목욕 지원 경험이 있는 직원으로 변경'],['인수인계 진행',<span className="inline-progress"><Progress value={80}/><b data-i18n-ignore>4/5</b></span>]]}/></PeopleBody>})}>요청 상세</Button></>}/><dl className="handover-row"><div><dt>수급자</dt><dd>홍○○ 어르신</dd></div><div><dt>담당 변경</dt><dd>김○○ → 박○○</dd><small className="handover-note"><Icon name="star"/>목욕 지원 경험</small></div><div><dt>시작일</dt><dd><time data-i18n-ignore>{formatShortDate(addDays(getToday(),handoverStart),language)}</time><Badge tone="blue"><span data-i18n-ignore>{formatRelative(addDays(getToday(),handoverStart),language)}</span></Badge></dd></div></dl><div className="handover-items-head"><h3>인수인계 항목</h3><Progress value={handoverItems.filter(x=>x.doneAt!==undefined).length/handoverItems.length*100}/><span data-i18n-ignore>{`${handoverItems.filter(x=>x.doneAt!==undefined).length}/${handoverItems.length}`}</span></div><Checklist items={handoverItems}/><div className="match-footer"><p>마지막 항목은 새 담당자의 첫 방문 후 기록합니다.</p><Button tone="primary" onClick={()=>open({title:'홍○○ 어르신 인수인계 내용',tag:'연속성 확인',tone:'teal',render:({close})=><PeopleBody close={close} target="새 담당자 박○○ 요양보호사에게"><InfoList rows={[['돌봄 목표','선택권을 보장하며 안전하게 목욕에 참여하도록 지원'],['선호','가능한 활동은 직접 · 목욕 전 순서를 미리 알고 싶어 함 · 오후 목욕 선호(10월 시범)'],['주의사항','욕실 미끄러짐 주의 · 물 온도 직접 확인'],['최근 개선 활동','목욕 시작 전 순서 설명(09.20–10.04 적용 중)'],['보호자 요청','낙상 위험 확인 · 가능하면 오전 목욕']]}/></PeopleBody>})}>인수인계 확인</Button></div></Card>}</div></Page>}

function Candidate({name,score,text,checks,selected,onSelect}){if(!checks)return <div className="candidate"><div><strong>{name}</strong><p>{text}</p></div><Badge tone="teal">{score}</Badge><Button>선택</Button></div>;const full=checks.every(Boolean);return <div className={cls('candidate','candidate-rich',selected&&'selected')}><div><strong>{name}</strong><p>{text}</p><ul className="condition-list">{['가능 시간','이동','경험','업무량'].map((c,i)=><li key={c} className={checks[i]?'ok':'warn'}><span aria-hidden="true">{checks[i]?'✓':'⚠'}</span>{c}</li>)}</ul></div><Badge tone={full?'success':'neutral'}>{score}</Badge><Button tone={selected?'primary':'default'} onClick={onSelect}>{selected?'선택됨':'선택'}</Button></div>}

