function Support({open}){const language=useLanguage();const[stage,setStage]=useState(null);const[changes,setChanges]=useState({});const setRow=(title,v)=>setChanges(c=>({...c,[title]:v}));const[query,setQuery]=useState('');const rows=supportRows.map(r=>({...r,...changes[r.title]})).filter(r=>(!stage||r.stage===stage)&&(!query||(r.title+r.text).includes(query)));const supportModal=r=>{const m=r.modal;if(m.kind==='health')return {...m,render:({close})=><SupportActionBody close={close} onConfirm={()=>setRow(r.title,{status:['진행 중','blue'],stage:'조치 중'})}/>};if(m.kind==='workload')return {...m,render:({close})=><IssueBody close={close} summary={['최○○ 요양보호사','연속 6일 근무','담당자 확인 완료']} sections={[['근무 현황','09.10–09.15 연속 6일 근무 · 이번 주 방문 20회'],['조정안','10.03(토) 휴무 추가 · 해당 방문 2건은 김○○이 대체'],['진행','담당자 확인 완료 → 대체 직원 확인 대기']]} primary={{label:'조정안 확정',onClick:()=>setRow(r.title,{status:['직원 확인 대기','warning']})}}/>};if(m.kind==='welfare')return {...m,render:({close})=><IssueBody close={close} summary={['김○○ 요양보호사',<><time data-i18n-ignore>{formatShortDate(addDays(getToday(),r.received),language)}</time> 신청</>,'증빙 제출 완료']} sections={[['신청 내용',<p className="record-conclusion">연 1회 건강검진 비용 지원 · 신청 <WonAmount n={150000}/> · 한도 <WonAmount n={200000}/></p>],['증빙','검진 영수증 1건 · 검진 확인서 1건'],['확인 사항','올해 지원 이력 없음 ✓ · 증빙 금액 일치 ✓']]} secondary={{label:'반려',onClick:()=>setRow(r.title,{status:['반려','neutral']})}} primary={{label:'승인',onClick:()=>setRow(r.title,{status:['승인 완료','success'],stage:'완료'})}}/>};return m};const elapsedText=n=>({ko:`${n}일째`,en:`Day ${n}`,ja:`${n}日目`}[language]);const overText={ko:'평균 초과',en:'over average',ja:'平均超過'}[language];return <Page><MetricStrip items={[{label:'미확인 요청',value:<CountValue n={1}/>,desc:'신규 접수 3건 중',tone:'red',icon:'alert'},{label:'처리 중',value:<CountValue n={7}/>,desc:'확인 완료 2 · 조치 중 5',tone:'orange',icon:'refresh'},{label:'평균 처리기간',value:'2.4일',desc:'최근 3개월',icon:'clock'},{label:'지원 만족도',value:'4.5/5',desc:'완료 후 응답',tone:'green',icon:'star'}]}/><Filters date={false} fields={[{label:'검색',search:true,value:query,onChange:setQuery,placeholder:'요청 제목이나 직원 이름을 검색하세요'},{label:'요청 유형',options:['건강·안전','업무 부담','복리후생']},{label:'담당 직원',options:['박○○','최○○','김○○']}]} onReset={()=>{setQuery('');setStage(null)}}/><div className="two-col wide-left"><Card className="support-requests"><SectionTitle title="직원 지원 요청" action={<>{stage&&<Button onClick={()=>setStage(null)}>전체 보기</Button>}<Button tone="primary">요청 등록</Button></>}/><div className="stage-tabs" role="tablist">{supportStages.map(([label,n,sub],i)=><button key={label} role="tab" aria-selected={stage===label} className={cls('stage-tab',stage===label&&'active')} onClick={()=>setStage(stage===label?null:label)}><small>{['①','②','③','④'][i]} {label}</small><strong data-i18n-ignore>{n}</strong>{sub&&<span>{sub}</span>}</button>)}</div><div className="support-table"><div className="support-row th"><span>유형</span><span>요청</span><span>접수</span><span>상태</span><span/></div>{rows.map(r=>{const date=addDays(getToday(),r.received);const n=-r.received+1;const over=r.stage!=='완료'&&n>SUPPORT_AVG_DAYS;return <button className="support-row" key={r.title} onClick={()=>open(supportModal(r))}><span><Badge tone="neutral" icon={r.icon}>{r.type}</Badge></span><span className="support-request"><strong>{r.title}</strong><small>{r.text}</small></span><span className="support-received"><time data-i18n-ignore>{formatShortDate(date,language)}</time>{r.stage!=='완료'&&<small className={over?'over':''} data-i18n-ignore>{over?`${elapsedText(n)} · ${overText}`:elapsedText(n)}</small>}</span><span><Badge tone={r.status[1]}>{r.status[0]}</Badge></span><Icon name="chev"/></button>})}{!rows.length&&<p className="empty-rows">해당 단계의 요청이 없습니다.</p>}</div></Card><Card className="support-analysis"><SectionTitle title="이번 달 요청 분석"/><h3>유형별 요청 수</h3><BarChart data={[['업무 부담',10],['복리후생',8],['건강·안전',6]]} max={10} format={v=>({ko:`${v}건`,en:String(v),ja:`${v}件`}[language])}/><h3>유형별 평균 처리기간</h3><BarChart data={[['업무 부담',3.1],['복리후생',2.2],['건강·안전',1.5]]} max={4} reference={SUPPORT_AVG_DAYS} toneFor={v=>v>SUPPORT_AVG_DAYS?'warning':''} format={v=>dayUnit(v,language)}/><p className="bar-reference-legend"><b aria-hidden="true"/>전체 평균 <span data-i18n-ignore>{dayUnit(SUPPORT_AVG_DAYS,language)}</span></p><p className="support-insight">업무 부담 요청이 가장 많고 처리도 가장 오래 걸려요. 연속 근무 조정 기준을 먼저 점검해 보세요.</p></Card></div></Page>}

const trainingPeople=[{name:'김○○',role:'요양보호사 · 2년 4개월',required:[2,2],rec:{title:'목욕 전 불안 대응',status:['배정 대기','neutral'],due:'09.27'},apply:'예정'},{name:'박○○',role:'요양보호사 · 1년 1개월',required:[1,2],rec:{title:'낙상·미끄러짐 예방',status:['수강 중','blue'],due:'09.30'},apply:'확인 대기'},{name:'최○○',role:'요양보호사 · 3년',required:[2,2],rec:null,apply:'확인 완료'}];
const applyTone={'예정':'neutral','확인 대기':'warning','확인 완료':'success'};
const applyPeriod={start:'2026-09-20',end:'2026-10-04'};
const applyVisits={before:['refuse','refuse','join','refuse'],after:[['2026-09-20','join'],['2026-09-22','refuse'],['2026-09-24','join']],remaining:['2026-10-01','2026-10-03']};
const judgmentOptions=[{key:'observe',label:'관찰 계속',recommended:true,cta:'관찰 계속으로 등록'},{key:'effect',label:'효과 확인',desc:'개인별 계획에 반영',cta:'효과 확인으로 등록'},{key:'change',label:'방법 변경',cta:'방법 변경으로 등록'}];
function monthDay(md){const[m,d]=md.split('.').map(Number);return new Date(getToday().getFullYear(),m-1,d)}
function VisitDot({result,date,language}){if(result==='pending')return <span className="visit-dot pending"><i/><small data-i18n-ignore>{formatShortDate(parseISO(date),language)}</small></span>;return <span className={cls('visit-dot',result)}><i aria-hidden="true">{result==='join'?'✓':'×'}</i>{date&&<small data-i18n-ignore>{formatShortDate(parseISO(date),language)}</small>}</span>}
function Education({open}){
  const language=useLanguage();
  const[tab,setTab]=useState('courses');
  const[judgment,setJudgment]=useState(null);
  const courseRows=[['노인인권 및 학대예방','필수','4명','09.30','3명 이수','해당 없음'],['목욕 전 불안 대응','추천','김○○','09.27','배정 대기','예정'],['낙상·미끄러짐 예방','안전','2명','10.05','수강 중','대기']];
  const start=parseISO(applyPeriod.start),end=parseISO(applyPeriod.end),today=getToday();
  const total=diffDays(end,start)+1,dayN=Math.min(total,Math.max(0,diffDays(today,start)+1)),left=Math.max(0,diffDays(end,today));
  const periodText={ko:`${dayN}일째 · ${left}일 남음`,en:`Day ${dayN} · ${left} days left`,ja:`${dayN}日目・残り${left}日`}[language];
  const remainingText=applyVisits.remaining.map(d=>formatShortDate(parseISO(d),language)).join(' · ');
  const picked=judgmentOptions.find(o=>o.key===judgment);
  const checkedText={ko:'확인 완료',en:'Checked',ja:'確認完了'}[language];
  const table=tab==='courses'?<div className="table"><div className="tr education-grid th">{['교육','구분','대상','기한','진행 상태','적용 확인'].map(x=><span key={x}>{x}</span>)}<span/></div>{courseRows.map(r=><button className="tr education-grid" key={r[0]} onClick={()=>open({title:`${r[0]} 교육 상세`,tag:r[1]})}>{r.map((x,index)=><span key={`${x}-${index}`}>{x}</span>)}<Icon name="chev"/></button>)}</div>
  :<div className="table"><div className="tr people-grid th"><span>직원</span><span>필수교육</span><span>추천교육</span><span>적용 확인</span><span/></div>{trainingPeople.map(p=>{const doneAll=p.required[0]===p.required[1];const due=p.rec&&monthDay(p.rec.due);const overdue=due&&diffDays(due)<0;return <button className="tr people-grid" key={p.name} onClick={()=>open({title:`${p.name} 교육 상세`,tag:'직원별 교육 현황'})}><span className="people-name"><strong>{p.name}</strong><small>{p.role}</small></span><span className={cls('required-progress',doneAll?'done':'partial')}><b data-i18n-ignore>{`${p.required[0]} / ${p.required[1]}`}</b><Progress value={p.required[0]/p.required[1]*100}/></span><span className="rec-cell">{p.rec?<><strong>{p.rec.title}</strong><span><Badge tone={p.rec.status[1]}>{p.rec.status[0]}</Badge><Badge tone={overdue?'danger':'warning'}><span data-i18n-ignore>{formatDue(due,language)}</span></Badge></span></>:<span className="muted-text">추천 교육 없음</span>}</span><span>{p.apply==='확인 완료'?<Badge tone="success"><span data-i18n-ignore>{checkedText}</span></Badge>:<Badge tone={applyTone[p.apply]}>{p.apply}</Badge>}</span><Icon name="chev"/></button>})}</div>;
  return <Page><MetricStrip items={[{label:'필수교육 이수율',value:'92%',desc:'대상 12명'},{label:'기한 초과',value:'1명',desc:'우선 확인',tone:'red'},{label:'추천교육 대기',value:'2건',desc:'기록 근거',tone:'orange'},{label:'적용 확인 대기',value:'3건',desc:'현장 기록 필요',tone:'blue'}]}/><div className="subtabs"><button className={tab==='courses'?'active':''} onClick={()=>setTab('courses')}>교육 과정</button><button className={tab==='people'?'active':''} onClick={()=>setTab('people')}>직원별 현황</button><button className={tab==='effect'?'active':''} onClick={()=>setTab('effect')}>교육 적용·효과</button></div>{tab!=='effect'?<Card className="education-table-card"><SectionTitle title={tab==='courses'?'교육 목록':'직원별 교육 현황'} action={<Button tone="primary">교육 배정</Button>}/>{table}</Card>
  :<div className="two-col wide-left"><Card className="apply-task"><SectionTitle title="적용 과제"/><div className="apply-head"><button className="apply-title" onClick={()=>open({title:'목욕 시작 전 순서 설명',tag:'적용 중',tone:'blue',render:({close})=><DetailBody close={close} info={[['교육 이수','김○○ · 목욕 전 불안 대응 09.19 이수'],['적용할 행동','순서를 설명하고 물 온도를 직접 확인하도록 선택권 제공']]} primary={{label:'방문 기록 3건 보기',stay:true,onClick:()=>open(visitRecordsModal())}}><ModalSection title="적용 기간 09.20–10.04"><div className="apply-period"><div><span/><b data-i18n-ignore>{periodText}</b></div><Progress value={dayN/total*100}/></div></ModalSection><ModalSection title="방문별 결과"><ApplyDots/></ModalSection></DetailBody>})}><strong>목욕 시작 전 순서 설명</strong><Icon name="chev"/></button><Badge tone="blue">적용 중</Badge></div><p className="apply-sub">김○○ → 홍○○ 어르신 · 목욕 전 불안 대응 교육 09.19 이수</p><div className="apply-action"><small>적용할 행동</small><p>순서를 설명하고 물 온도를 직접 확인하도록 선택권 제공</p></div><div className="apply-period"><div><span>적용 기간 09.20–10.04</span><b data-i18n-ignore>{periodText}</b></div><Progress value={dayN/total*100}/></div><div className="visit-dots"><div><small>적용 전</small><div>{applyVisits.before.map((r,i)=><VisitDot key={i} result={r} language={language}/>)}</div></div><div><small>적용 후</small><div>{applyVisits.after.map(([d,r])=><VisitDot key={d} result={r} date={d} language={language}/>)}{applyVisits.remaining.map(d=><VisitDot key={d} result="pending" date={d} language={language}/>)}</div></div></div><div className="visit-legend"><span><i className="join">✓</i>참여</span><span><i className="refuse">×</i>거부</span><span><i className="pending"/>남은 방문</span></div><div className="apply-footer"><Button onClick={()=>open(visitRecordsModal())}>방문 기록 3건 보기</Button></div></Card><Card className="education-effect"><SectionTitle title="적용 전후 변화"/><div className="compare"><div><small>적용 전 거부율</small><strong>75%</strong><span>4회 중 3회</span></div><Icon name="arrow"/><div><small>적용 후 거부율</small><strong className="improved">33%</strong><span>3회 중 1회</span></div></div><p className="effect-note">긍정적인 변화가 관찰됐지만 충분한 근거를 위해 2회 더 확인합니다. <b data-i18n-ignore>{{ko:`남은 방문 ${remainingText}`,en:`Remaining visits: ${remainingText}`,ja:`残りの訪問 ${remainingText}`}[language]}</b></p><div className="judgment-options" role="radiogroup">{judgmentOptions.map(o=><button key={o.key} role="radio" aria-checked={judgment===o.key} className={cls('judgment-option',judgment===o.key&&'selected')} onClick={()=>setJudgment(o.key)}><span className="radio-dot" aria-hidden="true"/><span><strong>{o.label}</strong>{o.desc&&<small>{o.desc}</small>}</span>{o.recommended&&<Badge tone="teal">추천</Badge>}</button>)}</div><div className="effect-actions"><Button tone="primary" onClick={()=>picked&&open({title:picked.cta,tag:'관리자 판단'})}>{picked?picked.cta:'판단을 선택하세요'}</Button></div></Card></div>}</Page>
}


const indicatorTabs=[['a','A. 오늘의 운영·기록'],['b','B. 수급자 중심'],['c','C. 개별 돌봄·개선'],['d','D. 직원 지원·연속성']];
const indicatorData={
 a:{title:'오늘의 운영·기록',desc:'계획된 방문과 돌봄 기록이 누락 없이 수행되는지 확인합니다.',metrics:[['방문 이행률','96%','계획 142건 중 완료 136건'],['기록 작성률','94%','완료 방문 136건 중 작성 128건'],['안전 보고 확인률','100%','발생 3건 모두 관리자 확인'],['지연·미방문 조치','5/6건','미완료 1건']],issues:[['기록 미작성','최○○ · 09.21 방문','danger'],['방문 지연 후 조치 대기','김○○ · 32분 지연','warning']]},
 b:{title:'수급자 중심 서비스',desc:'수급자 욕구와 직접 의견이 계획과 서비스 방법에 반영되는지 확인합니다.',metrics:[['욕구 반영률','89%','확인 욕구 47건 중 반영 42건'],['직접 의견 확인','91%','월 1회 이상 확인'],['보호자 요청 처리','93%','완료 14/15건'],['계획 검토 완료','8/10건','기한 내 완료']],issues:[['욕구 미반영','홍○○ · 목욕 시간 선호','danger'],['보호자 의견 충돌','김○○ · 외출 일정','warning']]},
 c:{title:'개별 돌봄·개선',desc:'발견된 문제에 맞춘 행동이 현장에서 적용되고 변화로 이어지는지 확인합니다.',metrics:[['개선 활동 진행','12건','확인 필요 3건'],['AI 제안 적용','8건','승인 제안 11건'],['효과 확인 완료','63%','적용 8건 중 5건'],['반복 문제 감소','7명','전월 대비 +2명']],issues:[['효과 확인 대기','홍○○ · 서비스 순서 설명','blue'],['반복 문제 증가','이○○ · 식사량 감소','danger']]},
 d:{title:'직원 지원·연속성',desc:'직원이 안정적으로 근무하고 담당 변경에도 서비스가 이어지는지 확인합니다.',metrics:[['필수교육 이수','92%','대상 12명'],['교육 현장 적용','75%','적용 대상 8건'],['직원 VOC 처리','88%','완료 14/16건'],['인수인계 완료','100%','이번 달 3건']],issues:[['교육 기한 초과','박○○ · 1건','danger'],['직원 확인 대기','지원 조치 2건','warning']]}
};
function metricPercent(value,index){const ratio=value.match(/(\d+)\/(\d+)/);if(ratio)return Math.round(Number(ratio[1])/Number(ratio[2])*100);if(value.includes('%'))return Number.parseFloat(value);return [96,94,78,84][index]}
function Indicators({kind='a',open}){const d=indicatorData[kind];const total=kind==='a'?94:kind==='b'?89:kind==='c'?72:88;return <Page><div className="subtabs indicator-tabs">{indicatorTabs.map(([k,l])=><button className={kind===k?'active':''} onClick={()=>location.hash=`/quality/indicators/${k}`} key={k}>{l}</button>)}</div><Card className="indicator-hero"><div><Badge tone="teal">핵심 서비스 지표 {kind.toUpperCase()}</Badge><h2>{d.title}</h2><p>{d.desc}</p></div><div className="ring" style={{'--score':`${total*3.6}deg`}}><strong>{total}%</strong><span>전체 충족</span></div></Card><div className="indicator-cards">{d.metrics.map((m,i)=><Card key={m[0]}><small>{m[0]}</small><strong>{m[1]}</strong><p>{m[2]}</p><Progress value={metricPercent(m[1],i)}/><Button onClick={()=>open({title:`${m[0]} 상세`,tag:`지표 ${kind.toUpperCase()}`,hideConfirm:true})}>근거 보기</Button></Card>)}</div><Card className="indicator-issues"><SectionTitle title="확인이 필요한 항목" desc="지표 수치에 영향을 주는 미완료 업무와 원본 기록입니다."/><IssueList>{d.issues.map(x=><Issue key={x[0]} tone={x[2]} tag={x[0]} title={x[1]} text="담당자와 처리 기한을 확인하세요." action={()=>open({title:x[0],tag:`지표 ${kind.toUpperCase()}`,tone:x[2],hideConfirm:true})}/>)}</IssueList></Card></Page>}

function Rights({open}){const[checked,setChecked]=useState(false);return <Page><MetricStrip items={[{label:'설명·동의 확인',value:'95%',desc:'이번 달 방문'},{label:'선택권 제공',value:'91%',desc:'관련 기록',tone:'green'},{label:'확인 필요',value:'2건',desc:'원본 기록 검토',tone:'red'},{label:'개선 반영',value:'6건',desc:'계획·교육',tone:'blue'}]}/><div className="two-col"><Card><SectionTitle title="핵심 원칙" desc="모든 방문과 기록에 적용"/><Checklist items={['서비스 전 이해할 수 있는 방식으로 설명','동의와 거부 의사 확인','거부를 문제행동으로 규정하거나 강요하지 않음','가능한 범위는 수급자가 직접 수행하도록 지원','선택 가능한 방법과 순서 제공','신체 노출과 개인 공간 보호','보호자 의견과 다를 때 수급자 의사 우선 확인']}/></Card><Card><SectionTitle title="확인 필요 신호" desc="담당자가 원본 기록을 확인"/><ul className="signal-list">{['반복되는 강한 거부','설명·동의 없이 수행된 기록','수급자 의사와 보호자 요청의 충돌','직원이 모든 활동을 대신 수행함','신체 노출·개인 공간 관련 불편','강압적 언어·행동 보고'].map(x=><li key={x}>{x}</li>)}</ul></Card></div><Card><SectionTitle title="확인이 필요한 권리·인권 문제" desc="AI는 문제를 확정하지 않고 관련 기록을 묶어 담당자의 확인을 돕습니다."/><IssueList><Issue tone="danger" tag="확인 필요" title="홍○○ 어르신" text="목욕 시작 전 거부 의사가 반복됐으나 개인별 계획 반영 전입니다." action={()=>open({title:'홍○○ 어르신 원본 기록 확인',tag:'권리·인권',tone:'danger',body:<RightsRecordBody/>,hideConfirm:true,actions:[{label:'개인별 계획 보기',to:'/care/plan'}]})}/><Issue tone="warning" tag="개선 중" title="김○○ 어르신" text="보호자 요청과 수급자의 외출 선호가 달라 상담을 진행 중입니다." action={()=>open({title:'김○○ 어르신 상담 기록',tag:'권리·인권',tone:'warning',body:<ConsultRecordBody/>,hideConfirm:true,actions:[{label:'개인별 계획 보기',to:'/care/plan'}]})}/><Issue tone="success" tag={checked?'확인 완료':'정상'} title="최○○ 어르신" text="서비스 순서 선택권 제공을 계획과 직원 교육에 반영했습니다." action={()=>open({title:'최○○ 어르신 개선 결과',tag:'권리·인권',tone:'success',render:({close})=><ModalShell close={close} primary={{label:'결과 확인 완료',onClick:()=>setChecked(true)}}><InfoList rows={[['반영 내용','서비스 순서 선택권 제공을 개인별 계획(09.26)과 직원 교육(09.19)에 반영'],['반영 후 변화','거부 표현 감소 · 직접 의견 “순서를 알려줘서 편해요”(09.28)'],['관련 증빙','개인별 계획 변경 이력 · 교육 이수증 · 돌봄 기록 3건']]}/></ModalShell>})}/></IssueList></Card></Page>}

const evidenceRows=[{name:'홍○○ 09.20 돌봄 기록',author:'김○○',type:'돌봄 기록',icon:'record',indicator:'수급자 중심',date:'09.20',status:'연결 완료'},{name:'9월 사례회의록',author:'이○○',type:'사례관리',icon:'case',indicator:'개별 돌봄·개선',date:'09.26',status:'확인 필요',reason:'메타정보 누락'},{name:'노인인권 교육 이수증',author:'박○○',type:'교육',icon:'edu',indicator:'권리·인권',date:'09.25',status:'연결 완료'}];
const evidenceTotals={all:284,review:8,recent:24};
function evidenceDate(md){const[m,d]=md.split('.').map(Number);return new Date(getToday().getFullYear(),m-1,d)}
function Evidence({open}){const language=useLanguage();const[chip,setChip]=useState('all');const[query,setQuery]=useState('');const rows=evidenceRows.filter(r=>(chip==='all'||(chip==='review'&&r.status==='확인 필요')||(chip==='recent'&&diffDays(evidenceDate(r.date))>-7))&&(!query||r.name.includes(query)));const total=evidenceTotals[chip];const shown={ko:`${total}건 중 ${rows.length}건 표시`,en:`Showing ${rows.length} of ${total}`,ja:`${total}件中${rows.length}件を表示`}[language];return <Page><Filters date={false} fields={[{label:'자료 검색',search:true,value:query,onChange:setQuery,placeholder:'자료명을 검색하세요'},{label:'자료 유형',options:['돌봄 기록','사례관리','교육']},{label:'관련 지표',options:['수급자 중심','개별 돌봄·개선','권리·인권']},{label:'기간',all:'이번 분기',options:['이번 달','최근 7일']}]} onReset={()=>{setQuery('');setChip('all')}}/><Card><SectionTitle title="증빙자료" action={<Button tone="primary">자료 등록</Button>}/><div className="evidence-chips">{[['all','전체',284],['review','확인 필요',8],['recent','최근 7일',24]].map(([key,label,n])=><button key={key} className={cls('evidence-chip',chip===key&&'active')} onClick={()=>setChip(key)} aria-pressed={chip===key}><span>{label}</span><b>{n}</b></button>)}</div><div className="table"><div className="tr evidence-grid-v2 th"><span>자료명</span><span>유형</span><span>관련 지표</span><span>작성일</span><span>상태</span><span/></div>{rows.map(r=><button className="tr evidence-grid-v2" key={r.name} onClick={()=>open({title:r.name,tag:'증빙자료',tone:'teal',render:({close})=><DetailBody close={close} info={[['유형',r.type],['관련 지표',r.indicator],['작성자',r.author],['작성일',r.date],['연결 상태',<Badge tone={r.status==='연결 완료'?'success':'warning'}>{r.status}</Badge>]]} primary={r.status==='확인 필요'?{label:'메타정보 입력'}:{label:'지표 연결 보기',to:'/improvement/org'}}><ModalSection title="내용 미리보기"><ul className="preview-lines">{(evidencePreviews[r.name]||[]).map(x=><li key={x}>{x}</li>)}</ul></ModalSection>{r.status==='확인 필요'&&<p className="record-signal">메타정보 누락 — 참석자 서명 정보가 없습니다.</p>}</DetailBody>})}><span className="evidence-name"><strong>{r.name}</strong><small>{r.author}</small></span><span className="evidence-type"><Icon name={r.icon}/>{r.type}</span><span>{r.indicator}</span><span>{r.date}</span><span className="evidence-status">{r.status==='연결 완료'?<Badge tone="success" icon="link">연결 완료</Badge>:<><Badge tone="warning" icon="warn">확인 필요</Badge><small>{r.reason}</small></>}</span><Icon name="chev"/></button>)}{!rows.length&&<p className="empty-rows">조건에 맞는 자료가 없습니다.</p>}</div><div className="table-pager"><span data-i18n-ignore>{shown}</span><div><Button>‹ 이전</Button><Button>다음 ›</Button></div></div></Card></Page>}
// Operations checklist: dates are offsets (days) from the reference date.
const opsTaskSeed=[{title:'수급자별 급여제공계획 정기 검토',owner:'이○○',cycle:'분기',due:-2},{title:'월간 돌봄 기록 확인',owner:'이○○',cycle:'매월',due:0},{title:'직원 필수교육 이수 확인',owner:'한○○',cycle:'매월',due:2},{title:'개인정보 접근 권한 점검',owner:'한○○',cycle:'분기',due:-1},{title:'보호자 요청 처리 결과 안내',owner:'이○○',cycle:'수시',due:1},{title:'직원 VOC 처리 결과 확인',owner:'한○○',cycle:'매월',due:-1,done:-2},{title:'증빙자료 누락 여부 확인',owner:'이○○',cycle:'매월',due:-3,done:-5},{title:'9월 급여 청구 자료 확인',owner:'한○○',cycle:'매월',due:-8,done:-9},{title:'낙상 위험 환경 점검',owner:'이○○',cycle:'분기',due:9},{title:'비상 연락망 업데이트',owner:'한○○',cycle:'수시',due:16}];
const makeOpsTasks=()=>opsTaskSeed.map((t,i)=>({id:i,title:t.title,owner:t.owner,cycle:t.cycle,due:addDays(getToday(),t.due),doneAt:t.done===undefined?null:addDays(getToday(),t.done)}));
function taskTone(t){if(t.doneAt)return 'done';const n=diffDays(t.due);if(n<0)return 'overdue';if(n<=3)return 'soon';return 'planned'}
function OpsCalendar({tasks,month,setMonth,day,setDay}){const language=useLanguage();const first=new Date(month.getFullYear(),month.getMonth(),1);const start=addDays(first,-((first.getDay()+6)%7));const cells=Array.from({length:42},(_,i)=>addDays(start,i));const monthTasks=tasks.filter(t=>t.due.getMonth()===month.getMonth()&&t.due.getFullYear()===month.getFullYear());const done=monthTasks.filter(t=>t.doneAt).length;const today=getToday();return <Card className="ops-calendar"><div className="ops-cal-head"><Button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}>‹</Button><h2 data-i18n-ignore>{formatMonth(month,language)}</h2><Button onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}>›</Button></div><div className="ops-cal-grid">{['월','화','수','목','금','토','일'].map(d=><b key={d}>{d}</b>)}{cells.map(c=>{const dayTasks=tasks.filter(t=>isSameDay(t.due,c));const tones=[...new Set(dayTasks.map(taskTone))];const other=c.getMonth()!==month.getMonth();return <button key={toISO(c)} className={cls('ops-cal-day',other&&'other',isSameDay(c,today)&&'today',day&&isSameDay(c,day)&&'picked')} onClick={()=>setDay(day&&isSameDay(c,day)?null:c)} disabled={!dayTasks.length} aria-label={toISO(c)} data-i18n-ignore><span>{c.getDate()}</span><i>{tones.map(t=><em key={t} className={t}/>)}</i></button>})}</div><div className="ops-cal-legend"><span><em className="overdue"/>기한 초과</span><span><em className="soon"/>3일 이내</span><span><em className="planned"/>예정</span><span><em className="done"/>완료</span></div><div className="ops-cal-progress"><div><strong>이번 달 진행률</strong><span data-i18n-ignore>{`${done}/${monthTasks.length}`}</span></div><Progress value={monthTasks.length?done/monthTasks.length*100:0}/></div></Card>}
function ChecklistPage({open}){const language=useLanguage();const openTask=t=>open({title:t.title,tag:'기한 관리',tone:'teal',render:({close})=><DetailBody close={close} info={[['담당자',t.owner],['반복 주기',t.cycle],['기한',<time data-i18n-ignore>{formatShortDate(t.due,language)}</time>],['상태',<span data-i18n-ignore>{t.doneAt?formatDone(t.doneAt,language):formatDue(t.due,language)}</span>]]} related="핵심 서비스 지표 · 증빙자료" primary={t.doneAt?undefined:{label:'완료 처리',onClick:()=>setTasks(ts=>ts.map(x=>x.id===t.id?{...x,doneAt:getToday()}:x))}}><ModalSection title="확인 항목"><CheckList items={(taskChecks[t.title]||['관련 자료 확인','처리 결과 기록']).map(x=>[x,!!t.doneAt])}/></ModalSection></DetailBody>});const[tasks,setTasks]=useState(makeOpsTasks);const[month,setMonth]=useState(()=>new Date(getToday().getFullYear(),getToday().getMonth(),1));const[day,setDay]=useState(null);const[showDone,setShowDone]=useState(false);const today=getToday();const inMonth=t=>t.due.getMonth()===today.getMonth()&&t.due.getFullYear()===today.getFullYear();const monthTasks=tasks.filter(inMonth);const doneCount=monthTasks.filter(t=>t.doneAt).length;const soon=tasks.filter(t=>taskTone(t)==='soon').length;const overdue=tasks.filter(t=>taskTone(t)==='overdue').length;const visible=tasks.filter(t=>!day||isSameDay(t.due,day));const open_=visible.filter(t=>!t.doneAt).sort((a,b)=>a.due-b.due);const done=visible.filter(t=>t.doneAt).sort((a,b)=>b.doneAt-a.doneAt);const toggle=id=>setTasks(ts=>ts.map(t=>t.id===id?{...t,doneAt:t.doneAt?null:getToday()}:t));const pct=monthTasks.length?Math.round(doneCount/monthTasks.length*100):0;
const row=t=>{const tone=taskTone(t);const status=t.doneAt?formatDone(t.doneAt,language):formatDue(t.due,language);return <div className={cls('ops-task',tone)} key={t.id} role="button" tabIndex={0} onClick={()=>openTask(t)} onKeyDown={e=>{if(e.key==='Enter')openTask(t)}}><input type="checkbox" checked={!!t.doneAt} onChange={()=>toggle(t.id)} onClick={e=>e.stopPropagation()} aria-label={t.title}/><div><strong>{t.title}</strong><small>{t.owner} · {t.cycle} · 기한 <time data-i18n-ignore>{formatShortDate(t.due,language)}</time></small></div><span className={cls('ops-status',tone)} data-i18n-ignore>{status}</span><Icon name="chev"/></div>};
return <Page><MetricStrip items={[{label:'이번 달 업무',value:<CountValue n={monthTasks.length}/>,desc:'정기 점검'},{label:'완료',value:<CountValue n={doneCount}/>,desc:`${pct}%`,tone:'green'},{label:'기한 임박',value:<CountValue n={soon}/>,desc:'3일 이내',tone:'orange'},{label:'기한 초과',value:<CountValue n={overdue}/>,desc:'우선 처리',tone:'red'}]}/><div className="ops-layout"><OpsCalendar tasks={tasks} month={month} setMonth={setMonth} day={day} setDay={setDay}/><Card><SectionTitle title="행정 체크리스트" action={<>{day&&<Button onClick={()=>setDay(null)}>전체 보기</Button>}<Button tone="primary">업무 추가</Button></>}/>{day&&<p className="ops-filter-note"><time data-i18n-ignore>{formatDate(day,language)}</time> · 기한 업무</p>}<div className="ops-task-list">{open_.map(row)}{!open_.length&&<p className="empty-rows">남은 업무가 없습니다.</p>}</div>{done.length>0&&<><button className="done-toggle" onClick={()=>setShowDone(v=>!v)} aria-expanded={showDone}><span data-i18n-ignore>{{ko:`완료 ${done.length}건`,en:`${done.length} completed`,ja:`完了${done.length}件`}[language]}</span> <span aria-hidden="true">{showDone?'▴':'▾'}</span></button>{showDone&&<div className="ops-task-list">{done.map(row)}</div>}</>}</Card></div></Page>}
function Reports({open}){return <Page><MetricStrip items={[{label:'생성 가능한 보고서',value:'4종',desc:'기관·수급자·직원'},{label:'이번 달 생성',value:'12건',desc:'다운로드 9건',tone:'blue'},{label:'보호자 공유',value:'5건',desc:'확인 완료 4건',tone:'green'},{label:'작성 대기',value:'2건',desc:'월간 보고',tone:'orange'}]}/><div className="report-grid">{[['기관 월간 서비스 보고서','운영·품질·개선 결과를 기관장에게 공유','기관장'],['수급자 월간 변화 보고서','생활 변화와 서비스 적용 결과를 정리','보호자'],['직원 교육·지원 보고서','교육 이수와 현장 적용, 지원 결과를 확인','관리자'],['핵심 서비스 지표 보고서','지표 현황과 근거 자료를 묶어 정리','기관']].map(r=><Card key={r[0]}><Badge tone="teal">{r[2]}</Badge><h2>{r[0]}</h2><p>{r[1]}</p><label><span>기간</span><select><option>2026년 9월</option></select></label><Button tone="primary" onClick={()=>open({title:`${r[0]} 미리보기`,tag:'보고서'})}>보고서 생성</Button></Card>)}</div></Page>}

function App(){const[route,go]=useHashRoute();const[modal,setModal]=useState(null);React.useEffect(()=>setModal(null),[route]);const content=useMemo(()=>{
  const props={open:setModal};
  if(route==='/operations/visits')return <OperationsVisits {...props}/>;
  if(route==='/operations/staff')return <OperationsStaff {...props}/>;
  if(route==='/improvement/org')return <ImprovementOrg {...props}/>;
  if(route==='/improvement/recipients')return <ImprovementRecipients {...props}/>;
  if(route==='/improvement/feedback')return <FeedbackPage {...props}/>;
  if(route==='/care/onboarding')return <Onboarding {...props}/>;
  if(route==='/care/plan')return <PlanPage {...props}/>;
  if(route==='/care/records/daily')return <CareDaily {...props}/>;
  if(route==='/care/records/weekly')return <Weekly {...props}/>;
  if(route==='/care/records/monthly')return <Monthly {...props}/>;
  if(route==='/staff/overview')return <StaffOverview {...props}/>;
  if(route==='/staff/attendance')return <Attendance {...props}/>;
  if(route==='/staff/matching')return <Matching {...props}/>;
  if(route==='/staff/support')return <Support {...props}/>;
  if(route==='/staff/education')return <Education {...props}/>;
  if(route.startsWith('/quality/indicators/'))return <Indicators kind={route.at(-1)} {...props}/>;
  if(route==='/quality/rights')return <Rights {...props}/>;
  if(route==='/quality/evidence')return <Evidence {...props}/>;
  if(route==='/quality/checklist')return <ChecklistPage {...props}/>;
  if(route==='/quality/reports')return <Reports {...props}/>;
  return <OperationsVisits {...props}/>;
},[route]);return <Layout route={route} go={go}>{content}<Modal modal={modal} onClose={()=>setModal(null)}/></Layout>}

export default App;
